param([int]$Port = 8501)  $agentRoot = Split-Path -Parent $MyInvocation.MyCommand.Path $codexPython = "C:\Users\Arian Zorrilla\.cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe" $dataset = Join-Path $agentRoot "data\source\SONIA_DESAFIO_03.zip" $backendRoot = Join-Path $agentRoot "BACK" $frontendRoot = Join-Path $agentRoot "FRONT"  if (-not (Test-Path -LiteralPath $codexPython)) { throw "No se encontro el Python de Codex." } if (-not (Test-Path -LiteralPath $dataset)) { throw "No se encontro el dataset en: $dataset" }  while (Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue) { $Port++ }  $env:PYTHONPATH = Join-Path $backendRoot "src" $env:SONIA_DATASET_PATH = $dataset $env:SONIA_FRONTEND_DIR = $frontendRoot $env:SONIA_HOST = "127.0.0.1" $env:SONIA_PORT = $Port  & $codexPython -c "import fastapi, openai, uvicorn" 2>$null if ($LASTEXITCODE -ne 0) {     Write-Host "Preparando la aplicacion por primera vez..."     & $codexPython -m pip install -e $backendRoot     if ($LASTEXITCODE -ne 0) { throw "No se pudieron instalar las dependencias del backend." } }  Write-Host "Iniciando SON-IA en http://127.0.0.1:$Port" Start-Process "http://127.0.0.1:$Port" & $codexPython -m collections_agent